import sqlite3
from datetime import datetime, timezone
SUPPORT_DB_PATH = 'support.db'

def revoke_customer_portal_access(contact_id: int, organization_id: int) -> dict:
    with sqlite3.connect(SUPPORT_DB_PATH) as conn:
        cur = conn.execute('DELETE FROM portal_access_grants WHERE contact_id = ? AND organization_id = ?', (contact_id, organization_id))
        revoked = cur.rowcount
        if revoked > 0:
            # Record when the contact's portal access was revoked
            revoked_at = datetime.now(timezone.utc).isoformat()
            conn.execute(
                'UPDATE customer_contacts SET portal_access_revoked_at = ? WHERE id = ? AND organization_id = ?',
                (revoked_at, contact_id, organization_id),
            )
    if revoked == 0:
        return {'status': 'not_found', 'contact_id': contact_id, 'organization_id': organization_id}
    return {'status': 'revoked', 'contact_id': contact_id, 'organization_id': organization_id, 'grants_removed': revoked}
